import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Tech Talk: Telemetry Dashboard","description":"","frontmatter":{"title":"Ceph Tech Talk: Telemetry Dashboard","date":"2022-05-06T00:00:00.000Z","updated":"2022-05-07T00:00:00.000Z","tags":["Ceph","Telemetry","Dashboard","Data Analysis","Crash Reporting"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Tech_Talk_-_Telemetry_Dashboard.md","filePath":"posts/2022/Ceph_Tech_Talk_-_Telemetry_Dashboard.md","lastUpdated":1780459816000}'),l={name:"posts/2022/Ceph_Tech_Talk_-_Telemetry_Dashboard.md"};function o(p,e,i,n,_,h){return r(),a("div",null,[...e[0]||(e[0]=[s("<p>Ceph Tech Talk: Telemetry Dashboard 介绍了 Ceph 分布式存储系统的遥测功能，重点讨论了遥测数据收集、分析以及如何通过仪表板进行可视化展示。</p><p><strong>主要内容包括</strong>：</p><ol><li><p><strong>遥测概述</strong>：Ceph 遥测允许集群自动收集匿名数据，包括配置、性能等，这些数据在公共仪表板上聚合展示，详细数据则在私有仪表板上提供。用户需明确同意许可协议才能启用遥测。</p></li><li><p><strong>遥测数据类型</strong>：遥测报告分为多个通道，包括基本通道、崩溃通道、设备通道、标识通道和性能通道。每个通道提供不同类型的信息，用户可以根据需要启用或禁用。</p></li><li><p><strong>隐私保护</strong>：Ceph 遥测非常重视用户隐私，收集的数据不包含任何敏感或标识信息，例如池名称、主机名称、对象名称或内容。所有数据都进行匿名化处理。</p></li><li><p><strong>开发者利益</strong>：遥测数据帮助开发者了解 Ceph 的实际使用情况、版本更新速度、用户部署的硬盘和 SSD 模型等信息，有助于改进产品设计和解决新问题。</p></li><li><p><strong>用户利益</strong>：用户可以通过遥测数据验证他们的安装，了解常见的部署模式，预防设备故障，并通过提供智能数据来帮助改进产品。</p></li><li><p><strong>遥测架构</strong>：遥测数据由集群中的管理器收集，然后发送到遥测后端，后端由 Apache 服务器、PostgreSQL 数据库和 Grafana 实例组成。</p></li><li><p><strong>崩溃报告</strong>：遥测数据中的崩溃通道提供原始崩溃报告，包括崩溃 ID、进程类型、版本、堆栈跟踪等信息。崩溃处理器对这些报告进行分析，生成签名并更新数据库。</p></li><li><p><strong>成功案例</strong>：遥测数据帮助开发者发现和修复了多个问题，例如文件存储的弃用决策、RBD 镜像部署的规模问题等。</p></li><li><p><strong>改进方向</strong>：Ceph 团队正在努力改进崩溃报告的签名生成和去重，以更好地帮助开发者解决问题。</p></li></ol><p><strong>标签</strong>：</p><ul><li>Ceph</li><li>Telemetry</li><li>Dashboard</li><li>Data Analysis</li><li>Crash Reporting</li></ul>",5)])])}const d=t(l,[["render",o]]);export{g as __pageData,d as default};
